import * as React from 'react';
import { cn } from '@/lib/utils';
import { Section, type SectionTone } from '../section/Section';
import type { ContainerWidth } from '../container/Container';

export type CTASectionTone = Extract<SectionTone, 'default' | 'muted' | 'brand' | 'inverse'>;

export type CTASectionProps = Omit<React.HTMLAttributes<HTMLElement>, 'title'> & {
  /** Headline for the call to action. */
  title: string;
  /** Supporting copy under the headline. */
  description?: string;
  /** Small overline above the headline. */
  eyebrow?: string;
  /** Buttons or links. */
  actions?: React.ReactNode;
  /** Surface treatment. Default 'inverse' for a contrasting band. */
  tone?: CTASectionTone;
  /** Copy alignment. Default 'center'. */
  align?: 'left' | 'center';
  /** Vertical space. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  /** Inner container width. Default 'lg'. */
  width?: ContainerWidth;
};

const sizePadding = {
  sm: 'md',
  md: 'lg',
  lg: 'xl',
} as const;

/**
 * Full-width conversion band: optional eyebrow, headline, supporting copy and
 * an action cluster. Use it at the end of a marketing page, between feature
 * sections, or after a content hub. Section owns the tone and spacing;
 * CTASection owns the centered content hierarchy.
 */
export const CTASection = React.forwardRef<HTMLElement, CTASectionProps>(function CTASection(
  {
    title,
    description,
    eyebrow,
    actions,
    tone = 'inverse',
    align = 'center',
    size = 'md',
    width = 'lg',
    className,
    ...props
  },
  ref
) {
  return (
    <Section
      ref={ref}
      tone={tone}
      padding={sizePadding[size]}
      width={width}
      className={className}
      {...props}
    >
      <div
        className={cn(
          'flex flex-col gap-5',
          align === 'center' ? 'items-center text-center' : 'items-start text-left'
        )}
      >
        {eyebrow && (
          <p className="text-xs font-semibold uppercase tracking-widest text-primary">{eyebrow}</p>
        )}
        <h2 className="max-w-3xl text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
          {title}
        </h2>
        {description && (
          <p className={cn('max-w-2xl text-base leading-relaxed text-muted-foreground sm:text-lg')}>
            {description}
          </p>
        )}
        {actions && (
          <div className={cn('mt-2 flex flex-wrap items-center gap-3', align === 'center' && 'justify-center')}>
            {actions}
          </div>
        )}
      </div>
    </Section>
  );
});

{
  "id": "cta-section",
  "name": "CTASection",
  "tier": "organism",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "cta-section",
  "exportName": "CTASection",
  "description": "Full-width conversion band with eyebrow, headline, supporting copy and actions.",
  "designIntent": "Every marketing page ends with the same call-to-action band, but teams rebuild the padding, width and tone each time. CTASection standardizes the hierarchy and defaults to an inverse band.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Headline for the call to action."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Supporting copy under the headline."
    },
    {
      "name": "eyebrow",
      "type": "string",
      "required": false,
      "description": "Small overline above the headline."
    },
    {
      "name": "actions",
      "type": "ReactNode",
      "required": false,
      "description": "Buttons or links."
    },
    {
      "name": "tone",
      "type": "'default' | 'muted' | 'brand' | 'inverse'",
      "required": false,
      "defaultValue": "inverse",
      "enum": [
        "default",
        "muted",
        "brand",
        "inverse"
      ],
      "description": "Surface treatment."
    },
    {
      "name": "align",
      "type": "'left' | 'center'",
      "required": false,
      "defaultValue": "center",
      "enum": [
        "left",
        "center"
      ],
      "description": "Copy alignment."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "sm",
        "md",
        "lg"
      ],
      "description": "Vertical space."
    },
    {
      "name": "width",
      "type": "'sm' | 'md' | 'lg' | 'xl' | 'full'",
      "required": false,
      "defaultValue": "lg",
      "enum": [
        "sm",
        "md",
        "lg",
        "xl",
        "full"
      ],
      "description": "Inner container width."
    }
  ],
  "examples": [
    {
      "title": "Default inverse CTA",
      "code": "<CTASection\n  eyebrow=\"Join Axial\"\n  title=\"Join the network\"\n  description=\"Connect with counterparties and close transactions.\"\n  actions={<Button>Get started</Button>}\n/>",
      "description": "A dark conversion band with one primary action."
    },
    {
      "title": "Muted CTA",
      "code": "<CTASection tone=\"muted\" align=\"left\" title=\"Talk to an advisor\" actions={<Button>Book a call</Button>} />",
      "description": "A lighter band aligned to the page grid."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't stack two CTA sections",
      "explanation": "One conversion band per page is enough. Put secondary actions in the hero or footer.",
      "example": "// Avoid\n<CTASection title=\"Join\" /><CTASection title=\"Join now\" />"
    }
  ],
  "accessibility": [
    {
      "feature": "Heading",
      "implementation": "Renders an h2 so it sits under the page h1",
      "userRequirements": "Keep the title short and make the primary action the first control"
    },
    {
      "feature": "Inverse tone",
      "implementation": "Section scopes inverse tokens for the band",
      "userRequirements": "Use semantic button variants so contrast survives the tone"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "CTA copy",
      "guidelines": [
        "State the outcome",
        "Use one primary verb",
        "Keep the supporting line to one sentence"
      ],
      "goodExamples": [
        "Join the network",
        "Get matched with an advisor"
      ],
      "badExamples": [
        "Submit",
        "Click here"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Section",
      "relationship": "CTASection renders Section internally; do not wrap it in another Section",
      "example": "<CTASection title=\"Ready?\" actions={<Button>Start</Button>} />"
    },
    {
      "component": "Button",
      "relationship": "Use one primary action and at most one secondary",
      "example": "<CTASection actions={<><Button>Start</Button><Button variant=\"outline\">Learn more</Button></>} />"
    }
  ],
  "relatedComponents": [
    "Section",
    "Hero",
    "Button"
  ]
}
